async function assessContent({text="",images=[],buffer=null,mime,stage}){const local=localModeration(text);if(local.decision==="block")return{...local,ipWarning:PROTECTED_REFERENCES.test(text),confidence:1,raw:{source:"local"}};const supplied=images.length?images:(buffer?[{buffer,mime}]:[]),ai=await geminiModeration({text,images:supplied,stage});if(PROTECTED_REFERENCES.test(text))ai.ipWarning=true;if(ai.ipWarning&&["publication","reported"].includes(stage)){ai.decision="quarantine";ai.category="intellectual_property";ai.reason="A recognisable character, brand, logo or public figure requires rights review before public publication."}return ai}
